parameters.jsCode:
const source = $("Code extrai inteligência").item.json;

const intelligence = source.extracted_intelligence || {};
const topics = intelligence.main_topics || [];

const title = source.title || "";
const city = source.city || "";
const country = source.country || "";
const audience = source.audience || "";
const officialText = source.official_page_text || "";
const newsText = source.news_context || "";
const researchSources = source.research_sources || [];

const topicSet = new Set(
  topics.map(t => String(t).toLowerCase())
);

const basicText = [
  title,
  audience,
  (source.tags || []).join(" "),
  topics.join(" ")
].join(" ").toLowerCase();

const fullText = [
  basicText,
  officialText,
  newsText
].join(" ").toLowerCase();

const hasTopic = (...names) =>
  names.some(name =>
    topicSet.has(name.toLowerCase())
  );

const contains = (text, ...terms) =>
  terms.some(term =>
    text.includes(term.toLowerCase())
  );


// CRYPTO CORE
const cryptoCore =
  hasTopic(
    "Blockchain",
    "Web3",
    "DeFi",
    "Stablecoins",
    "Bitcoin",
    "Tokenização"
  ) ||
  contains(
    basicText,
    "crypto",
    "cripto",
    "blockchain",
    "web3",
    "bitcoin"
  );


// STARTUP / INOVAÇÃO
const startupFocused =
  hasTopic(
    "Startups",
    "Inovação",
    "Venture Capital"
  ) ||
  contains(
    basicText,
    "startup",
    "founders",
    "venture capital",
    "innovation",
    "inovação"
  );


// INSTITUCIONAL
let institutionalScore = 0;

if (
  contains(
    fullText,
    "government",
    "governo",
    "gobierno",
    "reguladores",
    "regulators"
  )
) {
  institutionalScore += 2;
}

if (
  contains(
    fullText,
    "banking",
    "banks",
    "bancos",
    "sistema financeiro"
  )
) {
  institutionalScore += 2;
}

if (
  contains(
    fullText,
    "cbdc",
    "central bank",
    "banco central"
  )
) {
  institutionalScore += 2;
}

if (
  contains(
    fullText,
    "regulation",
    "regulación",
    "regulação"
  )
) {
  institutionalScore += 1;
}

if (
  contains(
    audience.toLowerCase(),
    "reguladores",
    "bancos",
    "instituições",
    "institutions"
  )
) {
  institutionalScore += 2;
}

const institutional =
  cryptoCore && institutionalScore >= 4;


// BUSINESS
let businessScore = 0;

if (
  contains(
    fullText,
    "business day",
    "c-level",
    "family office"
  )
) {
  businessScore += 3;
}

if (
  contains(
    fullText,
    "business development",
    "networking exclusivo",
    "networking exclusive"
  )
) {
  businessScore += 2;
}

if (
  contains(
    fullText,
    "venture capital",
    "investidores",
    "investors"
  )
) {
  businessScore += 1;
}

const businessHeavy =
  businessScore >= 3;


// PAGAMENTOS
const paymentsRelevant =
  hasTopic(
    "Pagamentos",
    "Stablecoins",
    "Fintech"
  ) ||
  contains(
    basicText,
    "payments",
    "pagamentos",
    "fintech",
    "stablecoin"
  );


// PERFIL
let eventProfile = "general";

if (cryptoCore && institutional) {
  eventProfile = "institutional_crypto";
}

else if (cryptoCore && businessHeavy) {
  eventProfile = "crypto_business";
}

else if (cryptoCore) {
  eventProfile = "crypto_ecosystem";
}

else if (startupFocused) {
  eventProfile = "startup_innovation";
}


// PACOTE FINAL PARA O MODELO
return {
  event_id: source.event_id,
  title,
  city,
  country,
  audience,

  main_topics: topics,

  organizer_name:
    intelligence.organizer_name || "",

  event_profile: eventProfile,

  signals: {
    crypto_core: cryptoCore,
    institutional,
    institutional_score: institutionalScore,
    startup_focused: startupFocused,
    business_heavy: businessHeavy,
    business_score: businessScore,
    payments_relevant: paymentsRelevant
  },

  official_page_text:
    officialText.slice(0, 12000),

  news_context:
    newsText.slice(0, 6000),

  research_sources: researchSources,

  research_confidence:
    intelligence.research_confidence || source.research_confidence
};
